record Loan(
    long id,
    long bookId,
    long borrowerId,
    String bookTitle,
    String borrowerName,
    LocalDate checkedOutAt,
    LocalDate dueDate,
    LocalDate returnedAt) {
  public Loan {
    Values.identity(id, 1);
    Values.identity(bookId, 1);
    Values.identity(borrowerId, 1);
    bookTitle = Values.text(bookTitle, 1, 200, "Accepted book title");
    borrowerName = Values.text(borrowerName, 1, 160, "Accepted borrower name");
    Values.date(checkedOutAt);
    if (dueDate != null && Values.date(dueDate).isBefore(checkedOutAt))
      throw new IllegalArgumentException("Due date precedes checkout.");
    if (returnedAt != null && Values.date(returnedAt).isBefore(checkedOutAt))
      throw new IllegalArgumentException("Return date precedes checkout.");
  }

  public Loan returned(LocalDate at) {
    if (returnedAt != null) throw new IllegalStateException("Loan already returned.");
    return new Loan(id, bookId, borrowerId, bookTitle, borrowerName, checkedOutAt, dueDate, at);
  }
}

// ---- src/librarytracker/storage/LibraryData.java ----
record LibraryData(
    long revision,
    long nextBookId,
    long nextBorrowerId,
    long nextLoanId,
    List<Book> books,
    List<Borrower> borrowers,
    List<Loan> loans) {
  public LibraryData {
    books = List.copyOf(books);
    borrowers = List.copyOf(borrowers);
    loans = List.copyOf(loans);
    if (revision < 0
        || nextBookId < 0
        || nextBorrowerId < 0
        || nextLoanId < 0
        || books.size() > 10000
        || borrowers.size() > 10000
        || loans.size() > 10000)
      throw new IllegalArgumentException("Invalid revision, identity watermark or capacity.");
    var bookMap = new HashMap<Long, Book>();
    var people = new HashMap<Long, Borrower>();
    var loanIds = new HashSet<Long>();
    var emails = new HashSet<String>();
    var activeLoans = new HashMap<Long, Loan>();
    for (Book b : books)
      if (bookMap.put(b.getId(), b) != null || b.getId() >= nextBookId)
        throw new IllegalArgumentException("Duplicate book or invalid watermark.");
    for (Borrower b : borrowers) {
      if (people.put(b.getId(), b) != null || b.getId() >= nextBorrowerId)
        throw new IllegalArgumentException("Duplicate borrower or invalid watermark.");
      if (b.getEmail() != null && !emails.add(b.getEmail()))
        throw new IllegalArgumentException("Borrower email is already registered.");
    }
    for (Loan loan : loans) {
      if (!loanIds.add(loan.id())
          || loan.id() >= nextLoanId
          || !bookMap.containsKey(loan.bookId())
          || !people.containsKey(loan.borrowerId()))
        throw new IllegalArgumentException("Invalid loan identity or reference.");
      if (loan.returnedAt() == null && activeLoans.put(loan.bookId(), loan) != null)
        throw new IllegalArgumentException("Book has more than one active loan.");
    }
    for (Book book : books) {
      Loan loan = activeLoans.get(book.getId());
      if (book.isCheckedOut() != (loan != null))
        throw new IllegalArgumentException("Current book state and active loan disagree.");
      if (loan != null
          && (!Objects.equals(book.getBorrowerId(), loan.borrowerId())
              || !Objects.equals(book.getCheckedOutAt(), loan.checkedOutAt())
              || !Objects.equals(book.getDueDate(), loan.dueDate())
              || !people.get(loan.borrowerId()).isActive()))
        throw new IllegalArgumentException("Active loan fields or borrower state disagree.");
    }
  }

  public static LibraryData empty() {
    return new LibraryData(0, 0, 0, 0, List.of(), List.of(), List.of());
  }
}

// ---- src/librarytracker/storage/FileStorage.java ----
/** One atomic aggregate replaces the original independently written book/borrower files. */
class FileStorage {
  public static final int MAX_BYTES = 10 * 1024 * 1024;
  private static final Map<Path, Object> LOCKS = new ConcurrentHashMap<>();
  private final Path directory, snapshotFile, booksFile, borrowersFile;
  private byte[] baseline, legacyBooks, legacyBorrowers;
  private LibraryData current;

  public FileStorage(Path directory) {
    this.directory = directory.toAbsolutePath().normalize();
    snapshotFile = this.directory.resolve("library.snapshot");
    booksFile = this.directory.resolve("books.txt");
    borrowersFile = this.directory.resolve("borrowers.txt");
  }

  public Path snapshotPath() {
    return snapshotFile;
  }

  private static byte[] read(Path path) throws IOException {
    if (Files.isSymbolicLink(path))
      throw new IOException("Symbolic-link data files are unsupported.");
    if (!Files.exists(path)) return null;
    if (!Files.isRegularFile(path) || Files.size(path) > MAX_BYTES)
      throw new IOException("Invalid data file or size exceeds 10 MiB.");
    byte[] bytes;
    try (var input = Files.newInputStream(path)) {
      bytes = input.readNBytes(MAX_BYTES + 1);
    }
    if (bytes.length > MAX_BYTES) throw new IOException("File exceeds 10 MiB.");
    return bytes;
  }

  public synchronized LibraryData load() throws IOException {
    byte[] snap = read(snapshotFile), books = null, borrowers = null;
    LibraryData parsed;
    if (snap != null) parsed = decode(snap);
    else {
      books = read(booksFile);
      borrowers = read(borrowersFile);
      if ((books == null) != (borrowers == null))
        throw new IOException(
            "Both legacy files are required; missing data is not an empty collection.");
      parsed = books == null ? LibraryData.empty() : legacy(books, borrowers);
    }
    baseline = snap;
    legacyBooks = books;
    legacyBorrowers = borrowers;
    current = parsed;
    return parsed;
  }

  public synchronized void save(LibraryData next) throws IOException {
    if (current == null) throw new IOException("Load before saving.");
    if (current.revision() == Long.MAX_VALUE
        || next.revision() != current.revision() + 1
        || next.nextBookId() < current.nextBookId()
        || next.nextBorrowerId() < current.nextBorrowerId()
        || next.nextLoanId() < current.nextLoanId())
      throw new IOException("Revision and allocation watermarks cannot move backward.");
    byte[] encoded = encode(next);
    Files.createDirectories(directory);
    Path lockPath = directory.resolve("library.lock");
    synchronized (LOCKS.computeIfAbsent(lockPath, p -> new Object())) {
      if (Files.isSymbolicLink(lockPath))
        throw new IOException("Symbolic-link locks are unsupported.");
      try (FileChannel channel = FileChannel.open(lockPath, CREATE, WRITE);
          var lock = channel.lock()) {
        if (!Arrays.equals(baseline, read(snapshotFile))
            || (baseline == null
                && (!Arrays.equals(legacyBooks, read(booksFile))
                    || !Arrays.equals(legacyBorrowers, read(borrowersFile)))))
          throw new IOException(
              "Library changed in another session. Reload and review before retrying.");
        Path temporary = Files.createTempFile(directory, ".library-save-", ".tmp");
        try {
          try (FileChannel out = FileChannel.open(temporary, WRITE, TRUNCATE_EXISTING)) {
            ByteBuffer bytes = ByteBuffer.wrap(encoded);
            while (bytes.hasRemaining()) out.write(bytes);
            out.force(true);
          }
          replaceAtomically(temporary, snapshotFile);
          baseline = encoded;
          legacyBooks = null;
          legacyBorrowers = null;
          current = next;
        } finally {
          Files.deleteIfExists(temporary);
        }
      }
    }
  }

  protected void replaceAtomically(Path source, Path target) throws IOException {
    Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
  }

  private static String utf8(byte[] bytes) throws IOException {
    return StandardCharsets.UTF_8
        .newDecoder()
        .onMalformedInput(CodingErrorAction.REPORT)
        .onUnmappableCharacter(CodingErrorAction.REPORT)
        .decode(ByteBuffer.wrap(bytes))
        .toString();
  }

  private static String text(String value) {
    return Base64.getEncoder()
        .encodeToString((value == null ? "" : value).getBytes(StandardCharsets.UTF_8));
  }

  private static String plain(String value) throws IOException {
    byte[] bytes = Base64.getDecoder().decode(value);
    if (!Base64.getEncoder().encodeToString(bytes).equals(value))
      throw new IOException("Non-canonical Base64.");
    return utf8(bytes);
  }

  private static String nullable(Object value) {
    return value == null ? "" : value.toString();
  }

  private static long number(String value) {
    if (!value.matches("0|[1-9][0-9]*")) throw new IllegalArgumentException("Invalid integer.");
    return Long.parseLong(value);
  }

  private static boolean bool(String value) {
    if (!value.equals("true") && !value.equals("false"))
      throw new IllegalArgumentException("Invalid boolean.");
    return value.equals("true");
  }

  private static LocalDate date(String value) {
    return value.isEmpty() ? null : LocalDate.parse(value);
  }

  public static byte[] encode(LibraryData data) throws IOException {
    StringBuilder out =
        new StringBuilder("LIBRARY2\n")
            .append(data.revision())
            .append('\t')
            .append(data.nextBookId())
            .append('\t')
            .append(data.nextBorrowerId())
            .append('\t')
            .append(data.nextLoanId())
            .append('\n');
    for (Book b : data.books())
      out.append("B\t")
          .append(b.getId())
          .append('\t')
          .append(b.getVersion())
          .append('\t')
          .append(text(b.getTitle()))
          .append('\t')
          .append(text(b.getAuthor()))
          .append('\t')
          .append(text(b.getIsbn()))
          .append('\t')
          .append(b.isActive())
          .append('\t')
          .append(b.isCheckedOut())
          .append('\t')
          .append(nullable(b.getBorrowerId()))
          .append('\t')
          .append(nullable(b.getCheckedOutAt()))
          .append('\t')
          .append(nullable(b.getDueDate()))
          .append('\n');
    for (Borrower b : data.borrowers())
      out.append("P\t")
          .append(b.getId())
          .append('\t')
          .append(b.getVersion())
          .append('\t')
          .append(text(b.getName()))
          .append('\t')
          .append(text(b.getEmail()))
          .append('\t')
          .append(text(b.getPhone()))
          .append('\t')
          .append(b.isActive())
          .append('\n');
    for (Loan l : data.loans())
      out.append("L\t")
          .append(l.id())
          .append('\t')
          .append(l.bookId())
          .append('\t')
          .append(l.borrowerId())
          .append('\t')
          .append(text(l.bookTitle()))
          .append('\t')
          .append(text(l.borrowerName()))
          .append('\t')
          .append(l.checkedOutAt())
          .append('\t')
          .append(nullable(l.dueDate()))
          .append('\t')
          .append(nullable(l.returnedAt()))
          .append('\n');
    out.append("END\t")
        .append(data.books().size())
        .append('\t')
        .append(data.borrowers().size())
        .append('\t')
        .append(data.loans().size())
        .append('\n');
    byte[] encoded = out.toString().getBytes(StandardCharsets.UTF_8);
    if (encoded.length > MAX_BYTES) throw new IOException("Snapshot exceeds 10 MiB.");
    return encoded;
  }

  public static LibraryData decode(byte[] bytes) throws IOException {
    if (bytes.length > MAX_BYTES) throw new IOException("Snapshot exceeds 10 MiB.");
    try {
      String[] lines = utf8(bytes).split("\n", -1);
      if (lines.length < 4 || !lines[0].equals("LIBRARY2") || !lines[lines.length - 1].isEmpty())
        throw new IOException("Invalid or truncated library snapshot.");
      String[] header = lines[1].split("\t", -1);
      if (header.length != 4) throw new IOException("Invalid header.");
      var books = new ArrayList<Book>();
      var borrowers = new ArrayList<Borrower>();
      var loans = new ArrayList<Loan>();
      for (int i = 2; i < lines.length - 2; i++) {
        String[] f = lines[i].split("\t", -1);
        switch (f[0]) {
          case "B" -> {
            if (f.length != 11) throw new IOException("Invalid book row.");
            books.add(
                new Book(
                    number(f[1]),
                    Math.toIntExact(number(f[2])),
                    plain(f[3]),
                    plain(f[4]),
                    plain(f[5]),
                    bool(f[6]),
                    bool(f[7]),
                    f[8].isEmpty() ? null : number(f[8]),
                    date(f[9]),
                    date(f[10])));
          }
          case "P" -> {
            if (f.length != 7) throw new IOException("Invalid borrower row.");
            borrowers.add(
                new Borrower(
                    number(f[1]),
                    Math.toIntExact(number(f[2])),
                    plain(f[3]),
                    plain(f[4]),
                    plain(f[5]),
                    bool(f[6])));
          }
          case "L" -> {
            if (f.length != 9) throw new IOException("Invalid loan row.");
            loans.add(
                new Loan(
                    number(f[1]),
                    number(f[2]),
                    number(f[3]),
                    plain(f[4]),
                    plain(f[5]),
                    date(f[6]),
                    date(f[7]),
                    date(f[8])));
          }
          default -> throw new IOException("Unknown row type.");
        }
      }
      if (!lines[lines.length - 2].equals(
          "END\t" + books.size() + "\t" + borrowers.size() + "\t" + loans.size()))
        throw new IOException("Invalid trailer or record counts.");
      return new LibraryData(
          number(header[0]),
          number(header[1]),
          number(header[2]),
          number(header[3]),
          books,
          borrowers,
          loans);
    } catch (IllegalArgumentException | ArithmeticException | java.time.DateTimeException e) {
      throw new IOException("Invalid library data: " + e.getMessage(), e);
    }
  }

  private static List<Map<String, String>> records(byte[] bytes, Set<String> keys)
      throws IOException {
    var records = new ArrayList<Map<String, String>>();
    var record = new LinkedHashMap<String, String>();
    String[] lines = utf8(bytes).split("\r?\n", -1);
    for (int i = 0; i < lines.length; i++) {
      String line = lines[i];
      if (line.isEmpty() && i == lines.length - 1) continue;
      if (line.equals("---")) {
        if (!record.keySet().equals(keys)) throw new IOException("Legacy record missing fields.");
        records.add(Map.copyOf(record));
        record.clear();
      } else {
        int split = line.indexOf('=');
        if (split < 1
            || !keys.contains(line.substring(0, split))
            || record.putIfAbsent(line.substring(0, split), line.substring(split + 1)) != null)
          throw new IOException("Unknown, duplicate or malformed legacy field.");
      }
    }
    if (!record.isEmpty()) throw new IOException("Legacy record missing closing separator.");
    return records;
  }

  private static LibraryData legacy(byte[] bookBytes, byte[] borrowerBytes) throws IOException {
    try {
      var books = new ArrayList<Book>();
      var borrowers = new ArrayList<Borrower>();
      var loans = new ArrayList<Loan>();
      for (var f :
          records(
              bookBytes,
              Set.of(
                  "id",
                  "title",
                  "author",
                  "isbn",
                  "checkedOut",
                  "borrowerId",
                  "checkedOutAt",
                  "dueDate")))
        books.add(
            new Book(
                number(f.get("id")),
                f.get("title"),
                f.get("author"),
                f.get("isbn"),
                bool(f.get("checkedOut")),
                f.get("borrowerId").isEmpty() ? null : number(f.get("borrowerId")),
                date(f.get("checkedOutAt")),
                date(f.get("dueDate"))));
      for (var f : records(borrowerBytes, Set.of("id", "name", "email", "phone")))
        borrowers.add(
            new Borrower(number(f.get("id")), f.get("name"), f.get("email"), f.get("phone")));
      for (Book b : books)
        if (b.isCheckedOut()) {
          Borrower borrower =
              borrowers.stream()
                  .filter(p -> p.getId() == b.getBorrowerId())
                  .findFirst()
                  .orElseThrow(
                      () ->
                          new IllegalArgumentException("Legacy loan references missing borrower."));
          loans.add(
              new Loan(
                  loans.size(),
                  b.getId(),
                  borrower.getId(),
                  b.getTitle(),
                  borrower.getName(),
                  b.getCheckedOutAt(),
                  b.getDueDate(),
                  null));
        }
      return new LibraryData(
          0,
          books.stream().mapToLong(Book::getId).max().orElse(-1) + 1,
          borrowers.stream().mapToLong(Borrower::getId).max().orElse(-1) + 1,
          loans.size(),
          books,
          borrowers,
          loans);
    } catch (IllegalArgumentException | ArithmeticException | java.time.DateTimeException e) {
      throw new IOException("Invalid legacy library: " + e.getMessage(), e);
    }
  }
}

// ---- src/librarytracker/service/LibraryManager.java ----
final class LibraryManager {
  private final FileStorage storage;
  private final Clock clock;
  private LibraryData data;

  public LibraryManager(FileStorage storage) throws IOException {
    this(storage, Clock.systemDefaultZone());
  }

  public LibraryManager(FileStorage storage, Clock clock) throws IOException {
    this.storage = storage;
    this.clock = clock;
    data = storage.load();
  }

  public synchronized void reload() throws IOException {
    data = storage.load();
  }

  public synchronized long revision() {
    return data.revision();
  }

  private void commit(
      List<Book> books,
      List<Borrower> borrowers,
      List<Loan> loans,
      long nextBook,
      long nextBorrower,
      long nextLoan)
      throws IOException {
    if (data.revision() == Long.MAX_VALUE) throw new IllegalStateException("Revision exhausted.");
    LibraryData candidate =
        new LibraryData(
            data.revision() + 1, nextBook, nextBorrower, nextLoan, books, borrowers, loans);
    storage.save(candidate);
    data = candidate;
  }

  private static void allocatable(long id) {
    if (id == Long.MAX_VALUE) throw new IllegalStateException("Ids exhausted.");
  }

  public synchronized List<Book> getAllBooks() {
    return data.books().stream().sorted(Comparator.comparingLong(Book::getId)).toList();
  }

  public synchronized List<Borrower> getAllBorrowers() {
    return data.borrowers().stream().sorted(Comparator.comparingLong(Borrower::getId)).toList();
  }

  public synchronized List<Loan> getLoanHistory() {
    return data.loans().stream().sorted(Comparator.comparingLong(Loan::id).reversed()).toList();
  }

  public synchronized List<Book> getCheckedOutBooks() {
    return getAllBooks().stream().filter(Book::isCheckedOut).toList();
  }

  public synchronized Optional<Book> findBookById(long id) {
    return data.books().stream().filter(b -> b.getId() == id).findFirst();
  }

  public synchronized Optional<Borrower> findBorrowerById(long id) {
    return data.borrowers().stream().filter(b -> b.getId() == id).findFirst();
  }

  public synchronized Optional<Borrower> findBorrowerForBook(Book book) {
    return book.getBorrowerId() == null ? Optional.empty() : findBorrowerById(book.getBorrowerId());
  }

  private Book book(long id, int version) {
    Book b = findBookById(id).orElseThrow(() -> new IllegalArgumentException("Book not found."));
    if (b.getVersion() != version)
      throw new IllegalStateException("Book version changed. Reload and review.");
    return b;
  }

  private Borrower borrower(long id, int version) {
    Borrower b =
        findBorrowerById(id).orElseThrow(() -> new IllegalArgumentException("Borrower not found."));
    if (b.getVersion() != version)
      throw new IllegalStateException("Borrower version changed. Reload and review.");
    return b;
  }

  private List<Book> replaceBook(Book replacement) {
    return data.books().stream()
        .map(b -> b.getId() == replacement.getId() ? replacement : b)
        .toList();
  }

  private List<Borrower> replaceBorrower(Borrower replacement) {
    return data.borrowers().stream()
        .map(b -> b.getId() == replacement.getId() ? replacement : b)
        .toList();
  }

  public synchronized Book addBook(String title, String author, String isbn) throws IOException {
    allocatable(data.nextBookId());
    Book b = new Book(data.nextBookId(), title, author, isbn);
    var books = new ArrayList<>(data.books());
    books.add(b);
    commit(
        books,
        data.borrowers(),
        data.loans(),
        data.nextBookId() + 1,
        data.nextBorrowerId(),
        data.nextLoanId());
    return b;
  }

  public synchronized Borrower registerBorrower(String name, String email, String phone)
      throws IOException {
    allocatable(data.nextBorrowerId());
    Borrower b = new Borrower(data.nextBorrowerId(), name, email, phone);
    var borrowers = new ArrayList<>(data.borrowers());
    borrowers.add(b);
    commit(
        data.books(),
        borrowers,
        data.loans(),
        data.nextBookId(),
        data.nextBorrowerId() + 1,
        data.nextLoanId());
    return b;
  }

  public synchronized Book editBook(long id, int version, String title, String author, String isbn)
      throws IOException {
    Book b = book(id, version).edit(title, author, isbn);
    commit(
        replaceBook(b),
        data.borrowers(),
        data.loans(),
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId());
    return b;
  }

  public synchronized Borrower editBorrower(
      long id, int version, String name, String email, String phone) throws IOException {
    Borrower b = borrower(id, version).edit(name, email, phone);
    commit(
        data.books(),
        replaceBorrower(b),
        data.loans(),
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId());
    return b;
  }

  public synchronized void deleteBook(long id, int version) throws IOException {
    book(id, version);
    if (data.loans().stream().anyMatch(l -> l.bookId() == id))
      throw new IllegalStateException("Book has loan history. Archive it instead.");
    commit(
        data.books().stream().filter(b -> b.getId() != id).toList(),
        data.borrowers(),
        data.loans(),
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId());
  }

  public synchronized void deleteBorrower(long id, int version) throws IOException {
    borrower(id, version);
    if (data.loans().stream().anyMatch(l -> l.borrowerId() == id))
      throw new IllegalStateException("Borrower has loan history. Archive the borrower instead.");
    commit(
        data.books(),
        data.borrowers().stream().filter(b -> b.getId() != id).toList(),
        data.loans(),
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId());
  }

  public synchronized void setBookActive(long id, int version, boolean active) throws IOException {
    Book old = book(id, version), b = old.setActive(active);
    if (b != old)
      commit(
          replaceBook(b),
          data.borrowers(),
          data.loans(),
          data.nextBookId(),
          data.nextBorrowerId(),
          data.nextLoanId());
  }

  public synchronized void setBorrowerActive(long id, int version, boolean active)
      throws IOException {
    Borrower old = borrower(id, version);
    if (!active
        && data.loans().stream().anyMatch(l -> l.borrowerId() == id && l.returnedAt() == null))
      throw new IllegalStateException("Return this borrower's active loans before archiving.");
    Borrower b = old.setActive(active);
    if (b != old)
      commit(
          data.books(),
          replaceBorrower(b),
          data.loans(),
          data.nextBookId(),
          data.nextBorrowerId(),
          data.nextLoanId());
  }

  public synchronized Loan checkOutBook(
      long bookId, int bookVersion, long borrowerId, LocalDate due) throws IOException {
    Book old = book(bookId, bookVersion);
    Borrower person =
        findBorrowerById(borrowerId)
            .orElseThrow(() -> new IllegalArgumentException("Borrower not found."));
    if (!person.isActive()) throw new IllegalStateException("Borrower is archived.");
    allocatable(data.nextLoanId());
    LocalDate at = LocalDate.now(clock);
    Book b = old.checkOut(borrowerId, at, due);
    Loan loan =
        new Loan(
            data.nextLoanId(), bookId, borrowerId, b.getTitle(), person.getName(), at, due, null);
    var loans = new ArrayList<>(data.loans());
    loans.add(loan);
    commit(
        replaceBook(b),
        data.borrowers(),
        loans,
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId() + 1);
    return loan;
  }

  public synchronized void returnBook(long bookId, int version) throws IOException {
    Book b = book(bookId, version).returnBook();
    Loan loan =
        data.loans().stream()
            .filter(l -> l.bookId() == bookId && l.returnedAt() == null)
            .findFirst()
            .orElseThrow(() -> new IllegalStateException("Active loan missing."));
    Loan returned = loan.returned(LocalDate.now(clock));
    commit(
        replaceBook(b),
        data.borrowers(),
        data.loans().stream().map(l -> l.id() == loan.id() ? returned : l).toList(),
        data.nextBookId(),
        data.nextBorrowerId(),
        data.nextLoanId());
  }

  public synchronized List<Book> searchBooks(String query, String status) {
    if (query == null
        || query.length() > 200
        || !List.of("all", "available", "out", "archived").contains(status))
      throw new IllegalArgumentException("Invalid search or status.");
    String q = query.strip().toLowerCase(Locale.ROOT);
    return getAllBooks().stream()
        .filter(
            b ->
                status.equals("all")
                    || (status.equals("archived")
                        ? !b.isActive()
                        : b.isActive() && (status.equals("out") == b.isCheckedOut())))
        .filter(
            b ->
                (b.getTitle() + " " + b.getAuthor() + " " + Objects.toString(b.getIsbn(), ""))
                    .toLowerCase(Locale.ROOT)
                    .contains(q))
        .toList();
  }
}

