// ─── tests ───
class FlakyStorage extends FileStorage {
    int failures;
    FlakyStorage(java.nio.file.Path dir, int failures) { super(dir); this.failures = failures; }
    @Override
    protected void replaceAtomically(java.nio.file.Path source, java.nio.file.Path target) throws java.io.IOException {
        if (failures > 0) { failures--; throw new java.io.IOException("simulated: disk full during the atomic move"); }
        super.replaceAtomically(source, target);
    }
}

class KataTest {
    public static void main(String[] args) {
        bootcamp.Check.test("a save whose atomic move failed can be retried and lands on disk", () -> {
            java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("bq-j2-kata-");
            LibraryManager m = new LibraryManager(new FlakyStorage(dir, 1));
            bootcamp.Check.raises(java.io.IOException.class, () -> m.addBook("Dune", "Frank Herbert", null));
            m.addBook("Dune", "Frank Herbert", null);
            bootcamp.Check.eq(new FileStorage(dir).load().books().size(), 1);
        });
        bootcamp.Check.test("a healthy save writes the snapshot", () -> {
            java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("bq-j2-kata-");
            LibraryManager m = new LibraryManager(new FlakyStorage(dir, 0));
            m.addBook("Dune", "Frank Herbert", null);
            m.addBook("Emma", "Jane Austen", null);
            bootcamp.Check.eq(new FileStorage(dir).load().books().size(), 2);
        });
        System.exit(bootcamp.Check.report());
    }
}
